const groups=[['UNIVERSO',[['robots','Robôs'],['parts','Equipamentos'],['campaign','Temporadas e missões'],['arena-config','Arena'],['combat','Regras de combate']]],['CARTEIRA',[['economy','Economia'],['deposits','Depósitos'],['withdrawals','Saques']]],['PILOTOS',[['users','Usuários e redes'],['guild-admin','Guildas e eventos'],['trade-admin','Mercado'],['coupon-admin','Cupons'],['chat-admin','Moderação'],['notices','Avisos globais']]],['IDENTIDADE',[['layout','Visual'],['audio','Músicas e efeitos'],['media','Arquivos'],['copy','Mensagens'],['activity','Atividade']]]];
export function adminStudio({state,tab,body,escape,icon,assetUrl}){return `<div class="admin-studio"><aside class="studio-navigation"><div class="studio-brand"><img src="${escape(assetUrl(state.settings.logoArt||'game-mark.png'))}" alt=""><span>LifeBots<small>CONTROLE DO UNIVERSO</small></span></div>${groups.map(([label,items])=>`<section><small>${label}</small>${items.map(([id,name])=>`<button data-a="admin-tab" data-id="${id}" class="${tab===id?'active':''}">${escape(name)}</button>`).join('')}</section>`).join('')}</aside><div class="studio-content"><div class="studio-stats"><article>${icon('robot')}<b>${state.catalog.length}</b><small>Modelos no universo</small></article><article>${icon('story')}<b>${state.chapters.length}</b><small>Missões e recompensas</small></article><article>${icon('users')}<b>${state.adminUsers?.length||'—'}</b><small>Pilotos registrados</small></article></div>${body}</div></div>`;}
